  }
  rows.sort((a: { quantitySold: number; name: string }, b: { quantitySold: number; name: string }): number => {
    if (b.quantitySold !== a.quantitySold) {
      return b.quantitySold - a.quantitySold;
    }
    if (a.name < b.name) {
      return -1;
    }
    if (a.name > b.name) {
      return 1;
    }
    return 0;
  });
